module TreasureMapReconstructor(\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] num_pieces,\n    input [3:0] piece_w [0:3],\n    input [3:0] piece_h [0:3],\n    input [3:0] piece_grid [0:3][0:3][0:3],\n    output reg [3:0] out_width,\n    output reg [3:0] out_height,\n    output reg [3:0] out_grid [0:15],\n    output reg [2:0] out_piece_map [0:15],\n    output reg done,\n    output reg valid\n);\n\n    // Parameters & localparams\n    localparam MAX_PIECES = 4;\n    localparam MAX_W = 4;\n    localparam MAX_H = 4;\n    localparam MAX_AREA = 16;\n    \n    // State definitions\n    localparam [2:0] IDLE             = 3'd0;\n    localparam [2:0] PREPARE          = 3'd1;\n    localparam [2:0] ENUM_WH          = 3'd2;\n    localparam [2:0] SOLVE            = 3'd3;\n    localparam [2:0] CHECK_CONSISTENCY= 3'd4;\n    localparam [2:0] OUTPUT           = 3'd5;\n\n    // Register declarations\n    reg [2:0] state, next_state;\n    reg [7:0] total_area;\n    reg [3:0] candidate_w;\n    reg [3:0] candidate_h;\n    reg [3:0] current_grid [0:15];\n    reg [2:0] current_piece_map [0:15];\n    reg [1:0] placed [0:3];          // Track placed pieces\n    reg [3:0] rotated_grids [0:3][0:3][0:3][0:3];  // [piece][rot][x][y]\n    reg [3:0] rotated_w [0:3];      // Width after rotation\n    reg [3:0] rotated_h [0:3];      // Height after rotation\n    reg [7:0] cycle_counter;        // Prevent infinite loops\n    reg solution_found;\n    reg [3:0] treasure_x, treasure_y;\n\n    // Backtracking stack\n    reg [1:0] stack_ptr;\n    struct packed {\n        reg [1:0] piece_idx;\n        reg [1:0] rotation;\n        reg [3:0] place_x;\n        reg [3:0] place_y;\n    } stack [0:3];\n\n    // Vectorized array for Manhattan calculation\n    reg [3:0] manhattan_grid [0:3][0:3];\n\n    // Main state machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            valid <= 1'b0;\n            out_width <= 4'd0;\n            out_height <= 4'd0;\n            cycle_counter <= 8'd0;\n            solution_found <= 1'b0;\n            stack_ptr <= 2'd0;\n\n            // Initialize arrays\n            for (integer i=0; i<16; i=i+1) begin\n                if (i < 4) begin\n                    placed[i] <= 2'd0;\n                    rotated_w[i] <= 4'd0;\n                    rotated_h[i] <= 4'd0;\n                    rotated_grids[i] <= '{default: 4'd0};\n                end\n                current_grid[i] <= 4'd0;\n                current_piece_map[i] <= 3'd0;\n                out_grid[i] <= 4'd0;\n                out_piece_map[i] <= 3'd0;\n            end\n        end else begin\n            cycle_counter <= cycle_counter + 8'd1;\n            state <= next_state;\n        end\n    end\n\n    // Next state logic\n    always @(*) begin\n        next_state = state;\n        case (state)\n            IDLE: begin\n                if (start) next_state = PREPARE;\n            end\n            PREPARE: begin\n                next_state = ENUM_WH;\n            end\n            ENUM_WH: begin\n                if ((candidate_w * candidate_h) == total_area) begin\n                    next_state = SOLVE;\n                end else if (candidate_w == MAX_W && candidate_h == MAX_H) begin\n                    next_state = OUTPUT;  // Enumeration exhausted\n                end\n            end\n            SOLVE: begin\n                if (stack_ptr == num_pieces) next_state = CHECK_CONSISTENCY;\n                else if (cycle_counter > 1000) next_state = OUTPUT;\n            end\n            CHECK_CONSISTENCY: begin\n                next_state = solution_found ? OUTPUT : SOLVE;\n            end\n            OUTPUT: begin\n                next_state = IDLE;\n            end\n            default: next_state = IDLE;\n        endcase\n    end\n\n    // FSM output logic\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Handled in state machine reset\n        end else begin\n            case (state)\n                PREPARE: begin\n                    cycle_counter <= 8'd0;\n                    solution_found <= 1'b0;\n                    // Calculate total area and precompute rotations\n                    total_area = 8'd0;\n                    for (int p=0; p<4; p=p+1) begin\n                        if (p < num_pieces) begin\n                            total_area = total_area + (piece_w[p] * piece_h[p]);\n                            // Precompute rotations\n                            for (int rotation=0; rotation<4; rotation=rotation+1) begin\n                                case (rotation)\n                                    2'd0: begin  // 0°\n                                        rotated_w[p] <= piece_w[p];\n                                        rotated_h[p] <= piece_h[p];\n                                        for (int x=0; x<4; x=x+1) begin\n                                            for (int y=0; y<4; y=y+1) begin\n                                                rotated_grids[p][rotation][x][y] <= x < piece_w[p] && y < piece_h[p] ? piece_grid[p][x][y] : 4'd0;\n                                            end\n                                        end\n                                    end\n                                    // ... other rotation cases ...\n                                endcase\n                            end\n                        end\n                    end\n                end\n\n                ENUM_WH: begin\n                    if (state == ENUM_WH && next_state == SOLVE) begin\n                        // Initialize grid for current candidate\n                        for (int i=0; i<16; i=i+1) begin\n                            current_grid[i] <= 4'd0;\n                            current_piece_map[i] <= 3'd0;\n                        end\n                        for (int p=0; p<4; p=p+1) placed[p] <= 2'd0;\n                        stack_ptr <= 2'd0;\n                    end else begin\n                        // Increment candidate dimensions\n                        if (candidate_w < MAX_W) candidate_w <= candidate_w + 4'd1;\n                        else begin\n                            candidate_w <= 4'd1;\n                            candidate_h <= candidate_h + 4'd1;\n                        end\n                    end\n                end\n\n                CHECK_CONSISTENCY: begin\n                    // Manhattan condition check\n                    solution_found <= 1'b0;\n                    for (int tx=0; tx<candidate_w; tx=tx+1) begin\n                        for (int ty=0; ty<candidate_h; ty=ty+1) begin\n                            manhattan_grid[tx][ty] = (current_grid[ty*candidate_w + tx] != 0) ? 1'b1 : 1'b0;\n                            // Validate entire grid against (tx,ty)\n                            for (int x=0; x<candidate_w; x=x+1) begin\n                                for (int y=0; y<candidate_h; y=y+1) begin\n                                    if (manhattan_grid[x][y] !== 4'd0) begin\n                                        // Check manhattan calculation\n                                        solution_found = (current_grid[y*candidate_w + x] === ((tx > x ? tx - x : x - tx) + (ty > y ? ty - y : y - ty)) % 10);\n                                    end\n                                end\n                            end\n                        end\n                    end\n                end\n\n                OUTPUT: begin\n                    done <= 1'b1;\n                    valid <= solution_found;\n                    if (solution_found) begin\n                        out_width <= candidate_w;\n                        out_height <= candidate_h;\n                        for (int i=0; i<16; i=i+1) begin\n                            out_grid[i] <= current_grid[i];\n                            out_piece_map[i] <= current_piece_map[i];\n                        end\n                    end\n                end\n            endcase\n        end\n    end\n\nendmodule